/bin/bash -lc 'work_tmp="${TMPDIR}/ghsimr-pages.Cm1z74"
for f in "$work_tmp"/about-ghsimr_ "$work_tmp"/contact-us_ "$work_tmp"/ghs-imr-pgdm-programme_ "$work_tmp"/pgdm-course-structure_ "$work_tmp"/pgdm-eligibility-and-fees-details_ "$work_tmp"/pgdm-admissions_ "$work_tmp"/pgdm-admission-process_ "$work_tmp"/additional-certifications_ "$work_tmp"/mba-admissions_; do
  printf '"'\\n=== %s ===\\n' \""'$(basename "$f")"
  python3 - "$f" <<'"'PY'
import sys,re
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.skip=0; self.tag=None; self.buf=[]; self.blocks=[]
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style','noscript','svg'): self.skip+=1; return
        if self.skip: return
        if tag in ('title','h1','h2','h3','h4','p','li','address'):
            if self.tag and self.buf: self.flush()
            self.tag=tag; self.buf=[]
    def handle_endtag(self,tag):
        if tag in ('script','style','noscript','svg'):
            if self.skip: self.skip-=1
            return
        if self.skip: return
        if tag==self.tag: self.flush()
    def handle_data(self,data):
        if not self.skip and self.tag: self.buf.append(data)
    def flush(self):
        s=re.sub(r'\\s+',' ',' '.join(self.buf)).strip()
        if s: self.blocks.append((self.tag,s))
        self.tag=None; self.buf=[]
with open(sys.argv[1],encoding='utf-8',errors='replace') as fh: p=P(); p.feed(fh.read())
for tag,s in p.blocks:
    if tag in ('title','h1','h2','h3','h4') or re.search(r'PGDM|Programme|Program|Admission|Eligibility|Duration|certificate|Kanpur|Gaur Hari|Singhania|address|campus|degree|diploma|speciali[sz]ation|Management|Finance|Marketing|Operations|Human Resource|Business Analytics|Information Technology',s,re.I):
        print(f'[{tag}] {s}')
PY
done
printf '\\n=== sitemap URLs ===\\n'
rg -o 'https://www\\.ghsimr\\.ac\\.in/["'^<" ]+'"' \""'$work_tmp/wp-sitemap.xml" | sed '"'s/&amp;/\\&/g' | sort -u | sed -n '1,260p'
printf '\\n=== API page URLs/titles ===\\n'
python3 - \""'$work_tmp/wp-json_wp_v2_pages_per_page_100__fields_link,slug,title" <<'"'PY'
import sys,json
with open(sys.argv[1],encoding='utf-8',errors='replace') as f: x=json.load(f)
for p in x:
 print(p.get('slug'), '|', p.get('title',{}).get('rendered'), '|', p.get('link'))
PY"

