class P(HTMLParser):
 def __init__(self): super().__init__(); self.intr=0; self.intd=0; self.row=[]; self.rows=[]; self.buf=[]
 def handle_starttag(self,t,a):
  if t=='tr': self.intr+=1; self.row=[]
  if self.intr and t in ('td','th'): self.intd+=1; self.buf=[]
 def handle_endtag(self,t):
